function TestRequestNode:Awake()
    SetButtonAction(self.Bg, Bind(self, self.OnClickCloseButtonHandler_))
    SetButtonAction(self.DreamSpaceBtn, Bind(self, self.OnClickDreamSpaceButtonHandler_))
    
    self:CreateParkourGameTestButton()

    ---@type UnityEngine.UI.GridLayoutGroup
    local gridLayout = self.Grids:GetComponent(typeof(GridLayoutGroup))
    gridLayout.cellSize = Vector2(300, 280)
    gridLayout.spacing = Vector2(60, 25)

    self.testEntryList_ = {
        {
            name = '测试主线关卡',
            tips = '请输入关卡id，不输入就是最后一关\n（新主线关卡/主线关卡表）',
            func = function(str)
                local questId = checkNumber(str)
                if questId <= 0 then
                    local maxQuestId = 0
                    ---@param questMainVo QuestMainVo
                    for _, questMainVo in ipairs(CfUtils.GetWholeVo(AutoIds.IdSetting280, 'QuestMainVo')) do
                        maxQuestId = math.max(maxQuestId, checkInt(questMainVo.id))
                    end
                    questId = maxQuestId
                end

                GameUtils.Request('OverseaMainQuest/passedNewQuestId', {questId = questId}, function(request, response)
                    if checkNumber(response.errCode) == 0 then
                        questComp._curQuestId = questId
                        questComp:UpdateMainQuestInfo(questId, true)
                        --questComp:UnlockFishPlaceState()
                    end
                end)
            end
        },
        {
            name = '中型pt临时入口',
            func = function(str)
                CfUtils.DialogOpen(Constants.UITypeIds.MediumPtMainDialog, nil, {
                    UIArgs(Constants.UITypeIds.UIHomeView)
                })
            end
        },
        {
            name = '抽卡效果测试',
            tips = '请输入卡牌id（角色表/角色卡牌表）',
            func = function(str)
                local cardId = checkInt(str)
                if cardId <= 0 then
                    GameUtils.Toast('Are you kidding me?')
                    return
                end

                local idType = GoodsUtils.GetIdType(cardId)
                if idType ~= Constants.IDType.CharacterCard then
                    GameUtils.Toast('噗噗~类型错误')
                    return
                end

                local gachaponResult    = {{goodsId = cardId, num = 1}}
                local GachaponUtils     = import('Game.Gachapon.GachaponUtils')
                local GachaponConstants = import('Game.Gachapon.GachaponConstants')
                GachaponUtils.GetGachaponComp().AllGachapon = GachaponUtils.GetGachaponComp().AllGachapon or {}
                GachaponUtils.GetGachaponComp().rookieCall  = GachaponUtils.GetGachaponComp().rookieCall or {}

                local rewardCardResult, statistic, rewardTopRare = GachaponUtils.CalcGachaponResult(gachaponResult)
                CfUtils.DialogOpen(Constants.UITypeIds.GachaponGuideAnim, {
                    result       = rewardCardResult,
                    statistic    = statistic,
                    topRare      = rewardTopRare,
                    Pool         = {poolType = GachaponConstants.PoolType.OverseaRegular, callTimes = 1, maxTimes = 1, oneConsume = {}, tenConsume = {}},
                    responseData = {},
                    jumpIndex    = 1,
                    CallType     = 1,
                })

                self:Close()
            end
        }
    }
