---@param luaIndex integer
---@param childNode UnityEngine.RectTransform
function TestRequestNode:OnUpdateEntryCellHandler_(luaIndex, childNode)
    childNode.name = string.fmt('Entry%1', luaIndex)

    local entryData = checkTable(self.testEntryList_[luaIndex])
    CfUtils.FillText(childNode:Find('Btn/Text'), entryData.name)
    
    ---@type UnityEngine.UI.InputField
    local inputField = childNode:Find('InputField'):GetComponent(typeof(InputField))
    CfUtils.FillCfText(inputField.placeholder, entryData.tips or '请输入...')
    CfUtils.SetTextFontSize(inputField.placeholder, 32)

    ---@type UnityEngine.RectTransform
    local inputFieldRt = inputField.gameObject.transform:GetComponent(typeof(RectTransform))
    inputFieldRt.sizeDelta = Vector2(280, 200)

    ---@type UnityEngine.RectTransform
    local entryBtn = childNode:Find('Btn'):GetComponent(typeof(RectTransform))
    entryBtn.sizeDelta = Vector2(280, 46)
    SetButtonAction(entryBtn, function()
        if entryData.func then
            entryData.func(inputField.text)
        end
    end)
end


