-- private
function TestRequestNode:CreateParkourGameTestButton()
    local btn = GameObject.Instantiate(self.DreamSpaceBtn.gameObject, self.DreamSpaceBtn.transform.parent)
    CfUtils.FillText(btn.transform:GetChild(0), 'ParkourGameTest')
    btn.transform.localPosition = self.DreamSpaceBtn.transform.localPosition + Vector3(300, 0, 0)
    SetButtonAction(btn, function()
        CfUtils.DialogOpen(Constants.UITypeIds.ParkourGameMainDialog, nil, {UIArgs(Constants.UITypeIds.UIHomeView)})
        self:Close()
    end)
end


return TestRequestNode
